// src/services/api.js  ← REEMPLAZA TODO EL ARCHIVO CON ESTO
const API_URL = "http://127.0.0.1:8000";

const getAuthHeaders = () => {
  const token = localStorage.getItem("access_token");
  return token ? { Authorization: `Bearer ${token}` } : {};
};

async function request(method, endpoint, body = null) {
  const config = {
    method,
    headers: {
      "Content-Type": "application/json",
      ...getAuthHeaders(),
    },
  };

  if (body) config.body = JSON.stringify(body);

  try {
    const response = await fetch(API_URL + endpoint, config);

    // Manejo de sesión expirada
    if (response.status === 401) {
      localStorage.removeItem("access_token");
      localStorage.removeItem("refresh_token");
      window.location.href = "/login";
      throw new Error("Sesión expirada");
    }

    // Intentar parsear JSON incluso si hay error
    let data;
    try {
      data = await response.json();
    } catch {
      data = { detail: "Error del servidor" };
    }

    if (!response.ok) {
      const errorMsg = data.detail || data.error || data.message || `Error ${response.status}`;
      throw new Error(errorMsg);
    }

    return data;
  } catch (err) {
    // Si ya lanzamos error arriba, no duplicar
    if (err.message.includes("Sesión expirada")) throw err;
    console.error(`Error en ${method} ${endpoint}:`, err);
    throw err;
  }
}

// Objeto api con métodos simples
export const api = {
  get: (endpoint) => request("GET", endpoint),
  post: (endpoint, body) => request("POST", endpoint, body),
  put: (endpoint, body) => request("PUT", endpoint, body),
  patch: (endpoint, body) => request("PATCH", endpoint, body),
  delete: (endpoint) => request("DELETE", endpoint),
};

// LOGIN
export async function login(username, password) {
  const response = await fetch(`${API_URL}/api/token/`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username, password }),
  });

  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.detail || "Usuario o contraseña incorrectos");
  }

  localStorage.setItem("access_token", data.access);
  localStorage.setItem("refresh_token", data.refresh);
  return data;
}

// FUNCIONES RÁPIDAS (TODAS CORREGIDAS Y FUNCIONANDO)
export const getMesas = async () => {
  const data = await api.get("/api/mesas/");
  return data; // El router ya devuelve la lista directamente
};

export const getEmpleados = () => api.get("/api/empleados/");
export const getPedidos = () => api.get("/api/pedidos/");
export const getProductos = () => api.get("/api/productos/");
export const crearPedido = (body) => api.post("/api/pedidos/", body);

export default api;
